import json, sys
path = sys.argv[1]
d = json.load(open(path))
r = d["rollout"]
sc = d["score"]
print("REWARD", sc.get("reward"))
print("FEEDBACK", str(sc.get("feedback"))[:700])
tr = r.get("trace") or r.get("output") or []
print("N_MSGS", len(tr))
for m in tr:
    if not isinstance(m, dict):
        continue
    role = m.get("role")
    if role == "user":
        print("[USER]", str(m.get("content"))[:400])
    elif role == "assistant":
        for tc in (m.get("tool_calls") or []):
            print("[ASST->TOOL]", tc.get("name"), json.dumps(tc.get("arguments"))[:300])
        if m.get("content"):
            print("[ASST]", str(m.get("content"))[:300])
    elif role == "tool":
        print("  [TOOLRES]", str(m.get("content"))[:220])
